"""Stylesheet for the trusted factory operations Site."""

STYLESHEET = r""":root{--f-bg:#0b121c;--f-panel:#121f2e;--f-border:#2b3b4c;--f-text:#e8f2fa;--f-muted:#94aabd;--f-blue:#80c8ff;--f-green:#60d9ac;--f-amber:#f6c876;--f-red:#ff838b}
#fleet-app{background:var(--f-bg);color:var(--f-text);font:14px/1.5 system-ui,-apple-system,sans-serif;min-height:100vh}
#fleet-app *{box-sizing:border-box}#fleet-app a{color:var(--f-blue);text-decoration:none}#fleet-app a:hover{text-decoration:underline}
#fleet-app button,#fleet-app input,#fleet-app select,#fleet-app textarea{font:inherit;color:inherit}#fleet-app button{cursor:pointer}
.f-layout{display:grid;grid-template-columns:218px minmax(0,1fr);min-height:100vh}.f-side{position:sticky;top:0;height:100vh;background:#0e1a27;border-right:1px solid var(--f-border);padding:23px 12px;display:flex;flex-direction:column}
.f-brand{display:flex;gap:10px;align-items:center;margin:0 10px 30px}.f-logo{background:#204f62;border:1px solid #3787a0;border-radius:11px;padding:9px;font-size:20px}.f-brand strong{font-size:17px}.f-brand small{display:block;color:var(--f-muted);font-size:11px}
.f-nav{display:grid;gap:3px}.f-nav button{border:0;border-radius:8px;background:transparent;color:#a6b6c7;padding:11px 13px;text-align:left;display:flex;justify-content:space-between}.f-nav button.active{background:#1c394c;color:#e0f5ff;border-left:3px solid var(--f-blue)}.f-nav small{font-size:11px;color:var(--f-muted)}
.f-foot{margin-top:auto;border-top:1px solid var(--f-border);padding:14px 10px 0;color:var(--f-muted);font-size:11px}
.f-main{max-width:1640px;margin:auto;padding:29px clamp(16px,3vw,44px) 60px}.f-top{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:22px}.f-top h1{font-size:27px;letter-spacing:-.7px;margin:4px 0}.f-eyebrow{font-size:10px;font-weight:750;letter-spacing:1.5px;text-transform:uppercase;color:var(--f-blue)}.f-muted{color:var(--f-muted)}.f-small{font-size:11px;color:var(--f-muted)}
.f-button{background:#1e3549;border:1px solid #39546d;padding:8px 11px;border-radius:8px;color:var(--f-text);display:inline-block}.f-button:hover{background:#2a475f}.f-buttons{display:flex;gap:8px;flex-wrap:wrap}
.f-kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:17px}.f-kpi,.f-panel{background:var(--f-panel);border:1px solid var(--f-border);border-radius:12px}.f-kpi{padding:15px}.f-kpi label{display:block;color:var(--f-muted);font-size:11px}.f-kpi strong{font-size:26px;display:block;margin:4px 0}.f-kpi small{font-size:10px;color:var(--f-muted)}
.f-panel{padding:19px;margin-bottom:16px}.f-panel h2{font-size:16px;margin:0 0 4px}.f-panel p{font-size:12px;color:var(--f-muted);margin:0 0 14px}.f-head{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;flex-wrap:wrap;margin-bottom:14px}
.f-status{display:inline-flex;align-items:center;gap:5px;border-radius:6px;padding:3px 8px;border:1px solid #4c5663;color:#b6c4d0;font-size:11px;white-space:nowrap}.f-status::before{content:"";width:6px;height:6px;background:currentColor;border-radius:50%}.f-status.good{color:var(--f-green);background:#15382e;border-color:#30614d}.f-status.warn{color:var(--f-amber);background:#352a1b;border-color:#6a542d}.f-status.bad{color:var(--f-red);background:#39222a;border-color:#764047}.f-status.info{color:var(--f-blue);background:#193448;border-color:#3a5f77}
.f-filters{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:15px}.f-filters input,.f-filters select,.f-field{border:1px solid var(--f-border);border-radius:8px;background:#0c1622;padding:8px 10px;min-width:0}.f-filters input{flex:1 1 110px;max-width:190px}.f-filters input:first-child{max-width:none;flex:2 1 210px}
.f-tablewrap{overflow:auto;border:1px solid var(--f-border);border-radius:9px}.f-table{width:100%;border-collapse:collapse;min-width:680px}.f-table th{background:#17283a;color:var(--f-muted);font-size:10px;text-transform:uppercase;letter-spacing:.5px;text-align:left;padding:10px}.f-table td{padding:11px;border-top:1px solid #29394a;font-size:12px;vertical-align:middle}.f-table tr:hover td{background:#1b2e40}.f-link{background:transparent;border:0;color:var(--f-blue)!important;padding:0;text-align:left}.f-item{font-weight:650;color:var(--f-text)}
.f-attention{display:grid;gap:9px}.f-alert{display:flex;gap:12px;align-items:center;background:#162638;border:1px solid var(--f-border);padding:12px;border-radius:9px}.f-alert .f-number{flex:none;display:grid;place-items:center;width:30px;height:30px;border-radius:8px;background:#284156;color:var(--f-blue);font-weight:700}.f-alert .f-grow{flex:1;min-width:0}.f-alert strong{display:block;font-size:13px}.f-alert small{display:block;color:var(--f-muted);font-size:11px;margin-top:3px}.f-alert .f-next{font-size:11px;color:var(--f-amber)}
.f-note{border-left:3px solid var(--f-blue);background:#1a2b3b;border-radius:5px;padding:12px 14px;color:#bdd0df;font-size:12px;margin-bottom:15px}.f-empty{border:1px dashed var(--f-border);padding:26px;text-align:center;color:var(--f-muted);border-radius:8px}.f-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}
.f-drawer{position:fixed;inset:0;z-index:30;background:#050a11bb;display:flex;justify-content:flex-end}.f-drawer aside{width:min(560px,100vw);height:100%;overflow:auto;background:#111f2e;border-left:1px solid var(--f-border);padding:25px}.f-drawer h2{font-size:21px;margin:12px 0}.f-drawer pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0b1420;border:1px solid var(--f-border);border-radius:9px;padding:13px;font-size:11px;max-height:360px;overflow:auto}.f-fact{display:grid;grid-template-columns:100px 1fr;gap:10px;padding:10px 0;border-bottom:1px solid var(--f-border);font-size:12px}
@media(max-width:1050px){.f-kpis{grid-template-columns:repeat(3,1fr)}.f-grid{grid-template-columns:1fr}}@media(max-width:680px){.f-layout{display:block}.f-side{position:static;height:auto;padding:10px}.f-brand{margin:0 0 10px}.f-nav{display:flex;overflow:auto}.f-nav button{white-space:nowrap;padding:9px}.f-foot{display:none}.f-main{padding:17px 12px 50px}.f-top h1{font-size:24px}.f-kpis{grid-template-columns:repeat(2,1fr)}.f-panel{padding:13px}.f-alert{flex-wrap:wrap}}"""
